import re


class SyntaxError(Exception):
    pass


class NameError(Exception):
    pass


class ZeroDivisionError(Exception):
    pass


def tokenize(code: str) -> list:
    """Kodu tokenlara ayır."""
    tokens = []
    i = 0
    n = len(code)

    while i < n:
        # Boşlukları atla
        if code[i].isspace():
            i += 1
            continue

        # Yorum satırı (#'den sonra kalanı atla)
        if code[i] == '#':
            while i < n and not code[i].isspace() and code[i] != '\n':
                i += 1
            continue

        # Sayı
        if code[i].isdigit() or (code[i] == '.' and i + 1 < n and code[i + 1].isdigit()):
            j = i
            while j < n and (code[j].isdigit() or code[j] in '.'):
                j += 1
            tokens.append(('NUM', code[i:j]))
            i = j
            continue

        # Değişken adı veya anahtar kelime
        if code[i].isalpha() or code[i] == '_':
            j = i
            while j < n and (code[j].isalnum() or code[j] == '_'):
                j += 1
            word = code[i:j]
            # Anahtar kelimeleri kontrol et
            if word in ('and', 'or', 'not', 'in', 'is', 'for', 'while', 'if', 'else', 'try', 'except', 'finally', 'with', 'as'):
                raise SyntaxError(f"Geçersiz anahtar kelime: {word}")
            tokens.append(('NAME', word))
            i = j
            continue

        # Operatörler ve parantezler
        if code[i] in '+-*/%()[]{}':
            tokens.append(('OP', code[i]))
            i += 1
            continue

        raise SyntaxError(f"Bilinmeyen karakter: {code[i]}")

    return tokens


def parse_expression(tokens: list, pos: int) -> tuple:
    """İfade ağacı oluşturur. (node, new_pos) döndürür."""
    node = parse_term(tokens, pos)
    while node[0] is not None and isinstance(node[1], dict):
        op = node[1].get('op')
        if op in ('+', '-'):
            right = parse_term(tokens, node[2])
            node = (node[0], {'op': op, 'left': node[1], 'right': right[0]}, right[1])
        else:
            break
    return node


def parse_term(tokens: list, pos: int) -> tuple:
    """Terim ağacı oluşturur. (node, new_pos) döndürür."""
    node = parse_factor(tokens, pos)
    while node[0] is not None and isinstance(node[1], dict):
        op = node[1].get('op')
        if op in ('*', '/', '%'):
            right = parse_factor(tokens, node[2])
            node = (node[0], {'op': op, 'left': node[1], 'right': right[0]}, right[1])
        else:
            break
    return node


def parse_factor(tokens: list, pos: int) -> tuple:
    """Faktör ağacı oluşturur. (node, new_pos) döndürür."""
    if pos >= len(tokens):
        raise SyntaxError("Beklenen ifade")

    token = tokens[pos]
    tok_type = token[0]

