        if pos + 1 < len(tokens) and tokens[pos + 1][0] == 'OP' and tokens[pos + 1][1] == '(':
            expr, new_pos = parse_expression(tokens, pos + 2)
            if new_pos >= len(tokens) or tokens[new_pos][0] != 'OP' or tokens[new_pos][1] != ')':
                raise SyntaxError("Beklenen parantez kapatma")
            return (expr, new_pos + 1)

